#' Annotated IHC Heatmap
#'
#' 
#' @param data .
#' @param markers .
#' @param subject .
#' @param group .
#' @param region .
#' @param scaling .
#' @param missing .
#' @param clusterRows .
#' @param clusterColumns .
#' @param interactive .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$markerSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rowOrder} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$heatmap} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$explorer} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$markerSummary$asDF}
#'
#' \code{as.data.frame(results$markerSummary)}
#'
#' @export
pyihcheatmap <- function(
    data,
    markers = NULL,
    subject = NULL,
    group = NULL,
    region = NULL,
    scaling = "raw",
    missing = "available",
    clusterRows = FALSE,
    clusterColumns = FALSE,
    interactive = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyihcheatmap requires jmvcore to be installed (restart may be required)")

    if ( ! missing(markers)) markers <- jmvcore::resolveQuo(jmvcore::enquo(markers))
    if ( ! missing(subject)) subject <- jmvcore::resolveQuo(jmvcore::enquo(subject))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(region)) region <- jmvcore::resolveQuo(jmvcore::enquo(region))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(markers), markers, NULL),
            `if`( ! missing(subject), subject, NULL),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(region), region, NULL))


    options <- pyihcheatmapOptions$new(
        markers = markers,
        subject = subject,
        group = group,
        region = region,
        scaling = scaling,
        missing = missing,
        clusterRows = clusterRows,
        clusterColumns = clusterColumns,
        interactive = interactive,
        showConsole = showConsole)

    analysis <- pyihcheatmapClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

